def gcd(x, y):
    while y:
        x, y = y, x % y
    return x

def lcm(x, y, gcd_val):
    return (x * y) // gcd_val

def binary_palindrome_changes(binary_str):
    changes = 0
    n = len(binary_str)
    for i in range(n // 2):
        if binary_str[i] != binary_str[n - i - 1]:
            changes += 1
    return changes

gcd_val = gcd(a, b)
binary_gcd = bin(gcd_val)[2:]
palindrome_changes = binary_palindrome_changes(binary_gcd)
lcm_val = lcm(a, b, gcd_val)
return gcd_val + (lcm_val % 100) + palindrome_changes

