def get_odd_collatz(n: int) -> dict:
    # Compute the Collatz sequence starting from a positive integer n,
#     then summarize the odd numbers encountered through multiple views.
#     :param n: int - A positive integer, the starting point of the Collatz sequence.
#     :return: dict - A dictionary with three keys:
