#           as they appear adjacently in the sequence.
#         * 'frequency': Dict[int, int] - a mapping from each odd number to its frequency of appearance.
#     The function first generates the full Collatz sequence from n down to 1.
#     It then extracts all odd numbers in order, counts their occurrences,
#     and groups consecutive odd numbers that occur in contiguous steps.
#     Examples:
#     >>> get_odd_collatz(1)
#     {'sorted_odds': [1], 'groups': ['1'], 'frequency': {1: 1}}
#     >>> get_odd_collatz(5)
#     {'sorted_odds': [1, 5], 'groups': ['5', '1'], 'frequency': {5: 1, 1: 1}}
#     >>> get_odd_collatz(12)
#     {'sorted_odds': [1, 3, 5], 'groups': ['3', '5', '1'], 'frequency': {3: 1, 5: 1, 1: 1}}
#     >>> get_odd_collatz(14)
#     {'sorted_odds': [1, 5, 7, 11, 13, 17], 'groups': ['7', '11', '17', '13', '5', '1'], 'frequency': {7: 1, 11: 1, 17: 1, 13: 1, 5: 1, 1: 1}}


        collatz_sequence = []
        while n != 1:
            collatz_sequence.append(n)
            if n % 2 == 0:
                n //= 2
            else:
                n = 3 * n + 1
        collatz_sequence.append(1)

        odd_numbers = [num for num in collatz_sequence if num % 2 != 0]
        sorted_odds = sorted(set(odd_numbers))

        groups = []
        current_group = []
        for num in odd_numbers:
