                current_group.append(num)
            else:
                groups.append(" ".join(map(str, current_group)))
                current_group = [num]
        if current_group:
            groups.append(" ".join(map(str, current_group)))

        frequency = {}
        for num in odd_numbers:
            frequency[num] = frequency.get(num, 0) + 1

        return {'sorted_odds': sorted_odds, 'groups': groups, 'frequency': frequency}



