def get_odd_collatz(n: int) -> dict:
    # Compute the Collatz sequence starting from a positive integer n,
#     then summarize the odd numbers encountered through multiple views.
#     :param n: int - A positive integer, the starting point of the Collatz sequence.
#     :return: dict - A dictionary with three keys:
#         * 'sorted_odds': List[int] - sorted list of all unique odd numbers appearing in the sequence.
#         * 'groups': List[str] - list of space-separated strings grouping consecutive odd numbers 
#           as they appear adjacently in the sequence.
#         * 'frequency': Dict[int, int] - a mapping from each odd number to its frequency of appearance.
#     The function first generates the full Collatz sequence from n down to 1.
#     It then extracts all odd numbers in order, counts their occurrences,
#     and groups consecutive odd numbers that occur in contiguous steps.
#     Examples:
#     >>> get_odd_collatz(1)
#     {'sorted_odds': [1], 'groups': ['1'], 'frequency': {1: 1}}
#     >>> get_odd_collatz(5)
